package com.bank.hierarchy;

import java.math.BigDecimal;

// An interface: pure contract, NO instance state, therefore NO constructor.
// Any field here would be implicitly public static final (a constant), not
// per-instance data, so there is nothing for a constructor to initialize.
public interface Chargeable {
    // A constant lives at interface-load time, not per object.
    BigDecimal MIN_CHARGE = new BigDecimal("50.00"); // implicitly public static final

    // Behaviour only — each implementer computes its own charge.
    BigDecimal monthlyCharge();

    // (Trying to write a constructor here, e.g. Chargeable() {}, is a compile error.)
}
