package com.bank.hierarchy;

import java.math.BigDecimal;

// Concrete subclass: implements the interface contract AND chains to the abstract
// class constructor with super(...). The abstract constructor does the shared setup.
public class SavingsAccount extends Account implements Chargeable {
    public SavingsAccount(String accountId, String holderName, BigDecimal balance) {
        super(accountId, holderName, balance); // runs the abstract Account constructor
    }

    @Override
    public BigDecimal monthlyCharge() {
        // Savings accounts are free above a threshold, else the minimum charge.
        return balance.compareTo(new BigDecimal("100000")) >= 0 ? BigDecimal.ZERO : MIN_CHARGE;
    }
}
