package com.bank.hierarchy;

import java.math.BigDecimal;

public class CurrentAccount extends Account implements Chargeable {
    private final BigDecimal flatFee;

    public CurrentAccount(String accountId, String holderName, BigDecimal balance, BigDecimal flatFee) {
        super(accountId, holderName, balance); // abstract constructor runs here too
        this.flatFee = flatFee;
    }

    @Override
    public BigDecimal monthlyCharge() {
        // Current accounts pay at least the minimum, or the flat fee, whichever is larger.
        return flatFee.compareTo(MIN_CHARGE) >= 0 ? flatFee : MIN_CHARGE;
    }
}
