package com.bank.hierarchy;

import java.math.BigDecimal;
import java.util.logging.*;

public class AccountHierarchyDemo {
    private static final Logger log = Logger.getLogger(AccountHierarchyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Each 'new' triggers the abstract Account constructor via super(...).
        SavingsAccount rajesh = new SavingsAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        CurrentAccount priya  = new CurrentAccount("CUR3001", "Priya Sharma", new BigDecimal("250000"), new BigDecimal("200.00"));

        BigDecimal rentAmount = new BigDecimal("50000");
        rajesh.debit(rentAmount);
        priya.credit(rentAmount);
        log.info(() -> "Transfer " + rentAmount + " from " + rajesh.getAccountId()
                + " to " + priya.getAccountId() + " SUCCESS");
        log.info(() -> "Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());

        // The interface contributed behaviour only; the charge differs per type.
        log.info(() -> "Rajesh (savings) monthly charge: " + rajesh.monthlyCharge());
        log.info(() -> "Priya (current) monthly charge: " + priya.monthlyCharge());

        // Note: you CANNOT write new Account(...) (abstract) or new Chargeable() (interface).
    }
}
